void tail_func(char tmp){
  if(tmp == 'U'){
    if(pos>7 && map[pos-8] != 'W'){
      tail[tailpos] = pos;
      if(tailpos>4){
        map[tail[tailpos-5]] = 'E';
      }
      tailpos++;
      pos-=8;
    }
  } else if (tmp == 'D'){
    if(pos<55 && map[pos+8] != 'W'){
      tail[tailpos] = pos;
      if(tailpos>4){
        map[tail[tailpos-5]] = 'E';
      }
      tailpos++;
      pos+=8;
    }
  } else if (tmp == 'R'){
    if(pos%8!=7 && map[pos+1] != 'W'){
      tail[tailpos] = pos;
      if(tailpos>4){
        map[tail[tailpos-5]] = 'E';
      }
      tailpos++;
      pos++;
    }
  } else if (tmp == 'L'){
    if(pos%8!=0 && map[pos-1] != 'W'){
      tail[tailpos] = pos;
      if(tailpos>4){
        map[tail[tailpos-5]] = 'E';
      }
      tailpos++;
      pos--;
    }
  }
}

