void insertion_sort_list(listint_t **list)
{
    listint_t *current;
    listint_t *sorted;
    if (list == NULL || *list == NULL || (*list)->next == NULL)
        return;
    sorted = *list;
    current = (*list)->next;
    while (current != NULL)
    {
        if (sorted != NULL &&  current->n < sorted->n)
        {
            current = swap(&current, &sorted);
            sorted = current->prev;
            if (sorted == NULL)
                *list = current;
            print_list(*list);
            while (sorted != NULL && current->n < sorted->n)
            {
                current = swap(&current, &sorted);
                sorted = current->prev;
                if (sorted == NULL)
                    *list = current;
                print_list(*list);
            }
        }
        else
        {
            sorted = current;
            current = sorted->next;
        }
    }
}

NODE insert(NODE first,int e,int pr)
{
    NODE temp=(NODE)malloc(sizeof(struct node));
    temp->data=e;
    temp->next=NULL;
    if (first==NULL)
        return temp;
    else if(first->next==NULL)
    {
        if (first->data>e)
        {
            temp->next=first;
            return temp;
        }
        else if(first->data<e)
            first->next=temp;
        else
        {
            if (pr==1)
                printf("Input not unique\n");
            free(temp);
        }
    }
    else
    {
        NODE m=first;
        while(m->next!=NULL && m->next->data<=e)
            m=m->next;
        if (m->data!=e)
        {
            temp->next=m->next;
            m->next=temp;
        }
        else
        {
            if (pr==1)
                printf("Input not unique\n");
            free(temp);
        }
        return first;
    }
}

