void swap_forward(listint_t *c)
{
    listint_t *tmp, *head;
    tmp = c->prev;
    if (tmp != NULL)
    {
        tmp->next = c->next;
        c->next->prev = tmp;
    }
    else
        c->next->prev = NULL;
    c->prev = c->next;
    if (c->next->next != NULL)
    {
        c->next = c->next->next;
        c->prev->next = c;
        c->next->prev = c;
    }
    else
    {
        c->next->next = c;
        c->next = NULL;
    }
    head = c;
    while (head->prev != NULL)
        head = head->prev;
    print_list(head);
    swap_backward(c->prev);
}

