int primo(long int num, long int vet[], int tam)
{    
    if (num == 1) return false;
    else if (num == 2) return true;
    else
    {
        for (int j = 0; j <= tam; j++)
        {
            if ((num % vet[j] == 0) && (num != vet[j]))
                return false;
        }
    }
    return true;
}

int delst(nptr* start,nptr* end)
{
    if(!*start)
    {
        printf("Underflow!!\n"); 
        return -99;
    }
    nptr temp; int x;
    temp=*start;
    x=temp->ele;
    if(!((*start)->rlink))
    {
        *end=*start=NULL;
        free(temp);
        return x;
    }
    *start=(*start)->rlink;
    (*start)->llink=NULL;
    free(temp);
    return x;
}

double Exp(int numero, int exponente)
{
    double Total = 1;
    int i = 0;
    do{
    Total *= numero;
    ++i;
    }while(i < exponente);
    return Total;
}

void println(LINE* ln, FILE* stream) {
    for(int i = 0; i < ln->count; i++) {
        fprintf(stream, "%s", ln->tokens[i]);
        if(i + 1 < ln->count)
            fprintf(stream, " ");
    }
    fprintf(stream, "\n");
}

