int binary_bitonic(int arr[],int str, int end ) 
{ 
    int mid; 
    mid = (str + end) / 2; 
    if(arr[mid] > arr[mid-1] && arr[mid] > arr[mid + 1]) 
    { 
        return mid; 
    } 
    else if(arr[mid] > arr[mid - 1] && arr[mid] < arr[mid + 1]) 
    { 
        binary_bitonic(arr, mid , end); 
    } 
    else if(arr[mid] < arr[mid - 1] && arr[mid] > arr[mid + 1]) 
    { 
        binary_bitonic(arr, str, mid); 
    } 
}

