    as = sgn(f(a)); 
    bs = sgn(f(b)); 
    if(as == bs){ 
        return -1; 
    }
    while(1){
        d = (a + b) / 2.0;
        fx = f(d);
        cs = sgn(fx);
        printf("now a = %lf\n", a);
        printf("now b = %lf\n", b);
        if(cs == as){
            a = d;
        }
        if(cs == bs){
            b = d;
        }
        if(fx == 0.0){ 
