void string_reverse(char *origin, char *rev) {
  int f = 0, cnt = 0, j = 0;
  while ( *(origin + f) != '\0' ) {
    cnt++;
    f++;
  }
  for (int i = cnt - 1; i >= 0; i--)
  {
    *(rev + j) = *(origin + i);
    j++;
  }
  *(rev + j) = '\0';
}

