struct Node *deleteByGivenKey(struct Node *head, int value)
{
     struct Node *p = head;
     struct Node *q = head->next;
     while (q->data != value) 
     {
          p = p->next;
          q = q->next;
     }
     if (q->data == value) 
     {
          p->next = q->next; 
          free(q);           
     }
     return head;
}

