int hexa_to_int(char s){
  if(s == 'a' || s == 'A')
    return 10;
  if(s == 'b' || s == 'B')
    return 11;
  if(s == 'c' || s == 'C')
    return 12;
  if(s == 'd' || s == 'D')
    return 13;
  if(s == 'e' || s == 'E')
    return 14;
  if(s == 'f' || s == 'F')
    return 15;
  return s - '0';
}

