int safe(int arr[N][N], int row, int col){
    int i,j;
    for ( i = 0; i < col; i++){
        if(arr[row][i])
            return 0;
    }
    for ( i = row, j = col; i >= 0 && j >= 0; i--, j--){
        if(arr[i][j])
            return 0;
    }
    for ( i = row, j = col; i < N && j >= 0; i++, j--){
        if(arr[i][j])
            return 0;
    }
    return 1;
