void pathCanonicalize(char_t *path)
{
   size_t i;
   size_t j;
   size_t k;
   i = 0;
   k = 0;
   while(path[i] != '\0')
   {
      if(path[i] == '/' || path[i] == '\\')
      {
         path[k++] = '/';
         while(path[i] == '/' || path[i] == '\\') i++;
      }
      else
      {
         path[k++] = path[i++];
      }
   }
   path[k] = '\0';
   i = 0;
   j = 0;
   k = 0;
   do
   {
      if(path[i] == '/' || path[i] == '\0')
      {
         if((i - j) == 1 && !osStrncmp(path + j, ".", 1))
         {
            if(k == 0)
            {
               if(path[i] == '\0')
               {
                  path[k++] = '.';
               }
               else if(path[i] == '/' && path[i + 1] == '\0')
               {
                  path[k++] = '.';
                  path[k++] = '/';
               }
            }
            else if(k > 1)
            {
               if(path[i] == '\0')
                  k--;
            }
         }
         else if((i - j) == 2 && !osStrncmp(path + j, "..", 2))
         {
            if(k == 0)
            {
               path[k++] = '.';
               path[k++] = '.';
               if(path[i] == '/')
                  path[k++] = '/';
            }
            else if(k > 1)
            {
               for(j = 1; j < k; j++)
               {
                  if(path[k - j - 1] == '/')
                     break;
               }
               if(j < k)
               {
                  if(!osStrncmp(path + k - j, "..", 2))
                  {
                     path[k++] = '.';
                     path[k++] = '.';
                  }
                  else
                  {
                     k = k - j - 1;
                  }
                  if(k == 0 && path[0] == '/')
                     path[k++] = '/';
                  else if(path[i] == '/')
                     path[k++] = '/';
               }
               else
               {
                  if(k == 3 && !osStrncmp(path, "..", 2))
                  {
                     path[k++] = '.';
                     path[k++] = '.';
                     if(path[i] == '/')
                        path[k++] = '/';
                  }
                  else if(path[i] == '\0')
                  {
                     k = 0;
                     path[k++] = '.';
                  }
                  else if(path[i] == '/' && path[i + 1] == '\0')
                  {
                     k = 0;
                     path[k++] = '.';
                     path[k++] = '/';
                  }
                  else
                  {
                     k = 0;
                  }
               }
            }
         }
         else
         {
            osMemmove(path + k, path + j, i - j);
            k += i - j;
            if(path[i] == '/')
               path[k++] = '/';
         }
         while(path[i] == '/') i++;
         j = i;
      }
   } while(path[i++] != '\0');
   path[k] = '\0';
}

